namespace sv_7f5cc72aaf6f455a85636851f683db04.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName => Warehouses
        .FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public static IReadOnlyList<WarehouseInfo> Warehouses { get; } = new List<WarehouseInfo>
    {
        new("WH-001", "Warehouse A – Downtown"),
        new("WH-002", "Warehouse B – Eastside"),
        new("WH-003", "Warehouse C – Airport"),
        new("WH-004", "Warehouse D – Harbor")
    };

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_7f5cc72aaf6f455a85636851f683db04.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private Timer? _timer;
    private int _subscriberCount;
    private readonly Lock _lock = new();

    public int CurrentLowStockCount { get; private set; }

    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Subscribe to polling. Polling starts when the first subscriber joins.
    /// </summary>
    public void StartPolling()
    {
        lock (_lock)
        {
            _subscriberCount++;
            if (_subscriberCount == 1)
            {
                _timer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
            }
        }
    }

    /// <summary>
    /// Unsubscribe from polling. Polling stops when the last subscriber leaves.
    /// </summary>
    public void StopPolling()
    {
        lock (_lock)
        {
            _subscriberCount = Math.Max(0, _subscriberCount - 1);
            if (_subscriberCount == 0)
            {
                _timer?.Dispose();
                _timer = null;
            }
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        CurrentLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately refresh when the warehouse changes
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        CurrentLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _timer?.Dispose();
    }
}

